import styled from 'styled-components'

export const Card = styled.div`
  background-color: #fff;
  border-radius: 8px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  overflow: hidden;
  width: 100%;
  max-width: 300px;
`

export const Imagem = styled.img`
  width: 100%;
  height: 200px;
  object-fit: cover;
`

export const Infos = styled.div`
  display: flex;
  gap: 8px;
  padding: 8px;
`

export const Descricao = styled.div`
  padding: 16px;
`

export const TituloContainer = styled.div`
  display: flex;
  justify-content: space-between; /* Separa título e nota */
  align-items: center;
  margin-bottom: 8px;
`

export const Titulo = styled.h2`
  font-size: 18px;
  font-weight: bold;
  margin: 0;
`

export const NotaContainer = styled.div`
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 16px;
  color: #ffcc00; /* Cor da nota e do ícone */
`

export const Button = styled.button`
  background-color: #007bff;
  color: #fff;
  border: none;
  padding: 8px 16px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 14px;
  margin-top: 16px;

  &:hover {
    background-color: #0056b3;
  }
`
